import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test15_executable';
const PORT = '/output/test15.mjs';

// mode: 'closed2' | 'open' | 'closed1' | 'closedboth'
function run(cmdArr, mode) {
  const redir = { closed2: '2>&-', open: '', closed1: '1>&-', closedboth: '1>&- 2>&-' }[mode];
  const script = `exec "$@" ${redir}`;
  const r = spawnSync('/bin/sh', ['-c', script, 'sh', ...cmdArr], {
    encoding: 'buffer', maxBuffer: 1 << 28, cwd: '/tmp',
  });
  return { out: (r.stdout ?? Buffer.alloc(0)).toString('latin1'), err: (r.stderr ?? Buffer.alloc(0)).toString('latin1'), code: r.status };
}
const norm = t => t.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const mode = process.argv[3] || 'closed2';
let fails = 0;
for (const argv of cases) {
  const a = run([EXE, ...argv], mode);
  const b = run([process.execPath, PORT, ...argv], mode);
  const p = [];
  if (a.out !== b.out) p.push('stdout');
  if (a.code !== b.code) p.push('exit');
  if (norm(a.err) !== norm(b.err)) p.push('stderr');
